 80      public static void validatePublicKey(SubjectPublicKeyInfo value) {
 81          // If RSA, do some other validations
 82          final ASN1ObjectIdentifier algorithmID = value.getAlgorithm().getAlgorithm();
 83          if (algorithmID.on(RSA_PARENT)) {
 84              validateRSAKey(value);
 85          } else if (algorithmID.equals(ECC_KEY)) {
 86              validateECCKey(value);
 87          } else {
 88              throw new PublicKeyException(String.format("Unsupported key type `%s`.", algorithmID.getId()));
 89          }
