 93      public static void verifySignature(String publicKeyPem, String snippet, String sigStr) {
 94          String keyStr = publicKeyPem
 95                  .replace("-----BEGIN PUBLIC KEY-----", "")
 96                  .replace("-----END PUBLIC KEY-----", "")
 97                  .replaceAll("[\n\r]+", "");
 98          sigStr = sigStr.replaceAll("[\n\r]+", "");
 99  
100          try {
101              byte[] keyBytes = Base64.getDecoder().decode(keyStr);
102              X509EncodedKeySpec keySpec = new X509EncodedKeySpec(keyBytes);
103              KeyFactory keyFactory = KeyFactory.getInstance("RSA");
104              PublicKey publicKey = keyFactory.generatePublic(keySpec);
105  
106              Signature signature = Signature.getInstance("SHA256withRSA");
107              signature.initVerify(publicKey);
108              signature.update(snippet.getBytes(StandardCharsets.UTF_8));
109              if (!signature.verify(Base64.getDecoder().decode(sigStr))) {
110                  throw new PublicKeyException("Key and signature do not match");
111              }
112          } catch (IllegalArgumentException e) {
113              throw new PublicKeyException("Invalid signature", e);
114          } catch (NoSuchAlgorithmException e) {
115              throw new PublicKeyException("Invalid algorithm", e);
116          } catch (GeneralSecurityException e) {
117              throw new PublicKeyException("Signature could not be verified.", e);
118          }
119      }
120  
121      private static void validateRSAKey(SubjectPublicKeyInfo value) {
122          // Should have a minimum length
123          try {
124              // Verifies the key is at least 4096 bits, which is 550 bytes of encoded data
125              if (value.getEncoded().length < 550) {
126                  throw new PublicKeyException("Public key must be at least 4096 bits.");
127              }
128          } catch (IOException e) {
129              throw new PublicKeyException("Cannot read public key.", e);
130          }
131  
132      }
