366      @SuppressWarnings("OptionalUsedAsFieldOrParameterType")
367      private OffsetDateTime handleExpirationTime(Optional<OffsetDateTimeParam> expiresQueryParam, Optional<CreateTokenRequest> token) {
368          // Compute default expiration
369          final OffsetDateTime now = OffsetDateTime.now(ZoneOffset.UTC);
370          final OffsetDateTime defaultExpiration = now.plus(this.policy.getExpirationPolicy().getExpirationOffset(), this.policy.getExpirationPolicy().getExpirationUnit());
371          final OffsetDateTime expiresBodyParam = token.map(CreateTokenRequest::getExpiresAt).orElse(null);
372  
373          // If a custom expiration is supplied use it, unless it violates our default policy
374          if (expiresQueryParam.isPresent() || expiresBodyParam!=null) {
375              final OffsetDateTime customExpiration = expiresBodyParam!=null ? expiresBodyParam:expiresQueryParam.get().get();
376  
377              // Verify custom expiration is not greater than policy
378              if (customExpiration.isAfter(defaultExpiration)) {
379                  throw new WebApplicationException("Cannot set expiration after policy default", Response.Status.BAD_REQUEST);
380              }
381  
382              // Verify is not already expired
383              if (customExpiration.isBefore(now)) {
384                  throw new WebApplicationException("Cannot set expiration before current time", Response.Status.BAD_REQUEST);
385              }
386              return customExpiration;
387          }
388          return defaultExpiration;
389      }
