391      @SuppressWarnings("JdkObsolete") // Date class is used by Jwt
392      private void handleJWTClaims(UUID organizationID, Claims claims) {
393          // Issuer and Sub must be present and identical
394          final String issuer = getClaimIfPresent("issuer", claims.getIssuer());
395          final String subject = getClaimIfPresent("subject", claims.getSubject());
396          if (!issuer.equals(subject)) {
397              throw new WebApplicationException("Issuer and Subject must be identical", Response.Status.BAD_REQUEST);
398          }
399  
400          // JTI must be present and have not been used in the past 5 minutes.
401          if (!this.cache.isJTIOk(getClaimIfPresent("id", claims.getId()), true)) {
402              logger.warn("JWT being replayed for organization {}", organizationID);
403              throw new WebApplicationException(INVALID_JWT_MSG, Response.Status.UNAUTHORIZED);
404          }
405  
406          // Ensure the expiration time for the token is not more than 5 minutes in the future
407          final Date expiration = getClaimIfPresent("expiration", claims.getExpiration());
408          if (OffsetDateTime.now(ZoneOffset.UTC).plusMinutes(5).isBefore(expiration.toInstant().atOffset(ZoneOffset.UTC))) {
409              throw new WebApplicationException("Not authorized", Response.Status.UNAUTHORIZED);
410          }
411      }

