181      public static KeyPair generateKeyPair(KeyType keyType) throws NoSuchAlgorithmException {
182          final KeyPairGenerator kpg = KeyPairGenerator.getInstance(keyType.getName());
183          if (keyType == KeyType.RSA) {
184              kpg.initialize(keyType.getKeySize());
185          } else {
186              ECGenParameterSpec spec = new ECGenParameterSpec("secp256r1");
187              try {
188                  kpg.initialize(spec);
189              } catch (InvalidAlgorithmParameterException e) {
190                  throw new IllegalArgumentException("Cannot generate key", e);
191              }
192          }
193          return kpg.generateKeyPair();
194      }
