134      private static void validateECCKey(SubjectPublicKeyInfo value) {
135          // Verify we have a supported curve, which is currently secp256r1 or secp384r1
136          final ASN1Primitive curveName = value.getAlgorithm().getParameters().toASN1Primitive();
137          if (!(curveName.equals(SECObjectIdentifiers.secp256r1) || curveName.equals(SECObjectIdentifiers.secp384r1))) {
138              throw new PublicKeyException(String.format("ECC curve `%s` is not supported.", curveName.toString()));
139          }
140      }
