145       * @param entity - {@link PublicKeyEntity} to convert
146       * @return - {@link PublicKey}
147       * @throws PublicKeyException - throws if the conversion fails
148       */
149      static PublicKey publicKeyFromEntity(PublicKeyEntity entity) {
150          X509EncodedKeySpec spec;
151          try {
152              final SubjectPublicKeyInfo publicKeySpec = entity.getPublicKey();
153              final String keyType = publicKeySpec.getAlgorithm().getAlgorithm().on(RSA_PARENT) ? "RSA" : "EC";
154              spec = new X509EncodedKeySpec(publicKeySpec.getEncoded());
155              return KeyFactory.getInstance(keyType).generatePublic(spec);
156          } catch (IOException | NoSuchAlgorithmException | InvalidKeySpecException e) {
157              throw new PublicKeyException("Cannot convert Key Spec to Public Key", e);
158          }
159      }
