590      /**
591       * Use constant time approach, to compare two byte arrays
592       * See also
593       * <a href="https://codahale.com/a-lesson-in-timing-attacks">A Lesson In Timing Attacks (or, Don’t use MessageDigest.isEquals)</a>
594       *
595       * @param a an array
596       * @param b an array
597       * @return true if both have same length and content
598       */
599      private static boolean safeEquals(byte[] a, byte[] b) {
600          if (a.length != b.length) {
601              return false;
602          }
603  
604          int result = 0;
605          for (int i = 0; i < a.length; i++) {
606              result |= a[i] ^ b[i];
607          }
608          return result == 0;
609      }
