18  /**
19   * DB backed {@link IRootKeyStore} using Hibernate as the underlying ORM
20   * This KeyStore generates a new RootKey for each ID that's passed in.
21   * By default, it generates RootKeys that are valid for 1 year, but that will eventually be changed
22   * This store assumes that the required tables and triggers are already setup.
23   * Currently, we do the migration in the dpc-attribution module, but that will probably need to be improved.
24   */
25  public class HibernateKeyStore implements IRootKeyStore {
26  
27      private final SessionFactory factory;
28      private final SecureRandom random;
29  
30      @Inject
31      public HibernateKeyStore(SessionFactory factory, SecureRandom random) {
32          this.factory = factory;
33          this.random = random;
34      }
35  
36      @Override
37      public IDKeyPair create() {
38          final UUID id = UUID.randomUUID();
39          final String rootKey = SecretHelpers.generateSecretKey(this.random);
40  
41          final RootKeyEntity entity = new RootKeyEntity();
42          final String idString = id.toString();
43          entity.setId(idString);
44          entity.setRootKey(rootKey);
45          final OffsetDateTime now = OffsetDateTime.now(ZoneOffset.UTC);
46          entity.setCreated(now);
47          // TODO: Make this configurable. DPC-284
48          entity.setExpires(now.plusYears(1));
49  
50          try (final Session session = this.factory.openSession()) {
51              final Transaction tx = session.beginTransaction();
52              try {
53                  session.persist(entity);
54                  tx.commit();
55              } catch (Exception e) {
56                  tx.rollback();
57                  throw new BakeryException(String.format("Cannot persist key to database. %s", e.getMessage()));
58              }
59          }
60  
61          return new IDKeyPair(idString, rootKey);
62      }
63  
64      @Override
65      public String generateKey() {
66          return SecretHelpers.generateSecretKey(this.random);
67      }
