182          final String plainText = "This should be encrypted";
183          final Cipher cipher = Cipher.getInstance("RSA");
184  
185          final KeyPairGenerator kpg = KeyPairGenerator.getInstance("RSA");
186          final KeyPair keyPair = kpg.generateKeyPair();
187          final String encoded = Base64.getMimeEncoder().encodeToString(keyPair.getPublic().getEncoded());
188          final String key = String.format("-----BEGIN PUBLIC KEY-----%n%s%n-----END PUBLIC KEY-----%n", encoded);
189          final SubjectPublicKeyInfo publicKeyInfo = PublicKeyHandler.parsePEMString(key);
190  
191          cipher.init(Cipher.ENCRYPT_MODE, keyPair.getPrivate());
192          final byte[] cipherText = cipher.doFinal(plainText.getBytes(StandardCharsets.UTF_8));
193  
194  
195          // Reconstruct the public key and try to decrypt
196          X509EncodedKeySpec spec = new X509EncodedKeySpec(publicKeyInfo.getEncoded());
197          final PublicKey rsa = KeyFactory.getInstance("RSA").generatePublic(spec);
198          cipher.init(Cipher.DECRYPT_MODE, rsa);
199          final byte[] decrypted = cipher.doFinal(cipherText);
200          assertEquals(plainText, new String(decrypted), "Should have matching plain text");
201      }
